ROT = os.path.join(os.path.dirname(__file__), "..", "lang")
os.makedirs(ROT, exist_ok=True)
for i, kod in [(1, "en"), (2, "pl"), (3, "ro")]:
    data = {"sprak": kod, "granskad": kod == "en",
            "text": {r[0]: r[i] for r in TEXT},
            "monster": {r[0]: r[i] for r in MONSTER}}
    with open(os.path.join(ROT, f"{kod}.json"), "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    print(kod, len(data["text"]), "texter,", len(data["monster"]), "mönster")
